const TERMINAL_OUTCOMES = new Set(['pass', 'reject', 'fail']);
const INCOMPLETE_STATUSES = new Set(['missing', 'timeout', 'crashed', 'skipped']);

function ratio(numerator, denominator) {
  return denominator === 0 ? null : Number((numerator / denominator).toFixed(6));
}

function expectedOutcome(anchor) {
  if (anchor === 'positive') return 'pass';
  if (anchor === 'negative') return 'reject';
  return 'pass';
}

function incompleteStatus(trial) {
  const status = String(trial?.status ?? '').toLowerCase();
  if (INCOMPLETE_STATUSES.has(status)) return status;
  if (status === 'crash') return 'crashed';
  if (status === 'skip') return 'skipped';
  return null;
}

/**
 * Aggregate deterministic reliability trials.
 *
 * A case is complete only when it contains exactly k terminal trials. Missing,
 * timeout, crashed and skipped trials make the case incomplete. Incomplete cases
 * remain visible in the result but are excluded from metric denominators.
 */
export function aggregateReliability(fixture) {
  const design = fixture?.design ?? {};
  const k = Number(design.k);
  const minCases = Number(design.minCases);
  const flakeThreshold = Number(design.flakeThreshold);
  const cases = Array.isArray(fixture?.cases) ? fixture.cases : [];

  if (!Number.isInteger(k) || k < 1) throw new TypeError('design.k must be a positive integer');
  if (!Number.isInteger(minCases) || minCases < 0) throw new TypeError('design.minCases must be a non-negative integer');
  if (!Number.isFinite(flakeThreshold) || flakeThreshold < 0 || flakeThreshold > 1) {
    throw new TypeError('design.flakeThreshold must be between 0 and 1');
  }

  const anchorAggregates = { positive: [], negative: [] };
  const incompleteCases = [];
  const safetyViolations = [];
  const anchorViolations = [];
  const flakeCaseIds = [];
  let completeCases = 0;
  let passK = 0;
  let passAtK = 0;
  let flake = 0;

  for (const source of cases) {
    const id = String(source?.id ?? '');
    const trials = Array.isArray(source?.trials) ? source.trials : [];
    const anchor = source?.anchor ?? null;
    const expected = expectedOutcome(anchor);
    const missingStatuses = trials.map(incompleteStatus).filter(Boolean);
    const hasWrongTrialCount = trials.length !== k;
    const isIncomplete = hasWrongTrialCount || missingStatuses.length > 0;

    if (isIncomplete) {
      const reason = hasWrongTrialCount ? 'trial-count' : missingStatuses[0];
      incompleteCases.push({
        id,
        scenarioId: source?.scenarioId ?? null,
        status: reason,
        trialCount: trials.length,
        expectedTrials: k,
        trials,
      });
      if (source?.safety === true && missingStatuses.includes('skipped')) {
        safetyViolations.push({ id, type: 'skip' });
      }
      continue;
    }

    completeCases += 1;
    const succeeded = trials.map((trial) => String(trial?.outcome ?? '') === expected);
    const allPassed = succeeded.every(Boolean);
    const anyPassed = succeeded.some(Boolean);
    if (allPassed) passK += 1;
    if (anyPassed) passAtK += 1;

    const firstFailed = String(trials[0]?.outcome ?? '') !== expected;
    const fixedOnRerun = firstFailed && trials.slice(1).length > 0 && trials.slice(1).every((trial) => String(trial?.outcome ?? '') === expected);
    const isFlake = fixedOnRerun;
    if (isFlake) {
      flake += 1;
      flakeCaseIds.push(id);
      if (source?.safety === true) safetyViolations.push({ id, type: 'flake' });
    }

    if (anchor === 'positive' || anchor === 'negative') {
      const aggregate = {
        id,
        scenarioId: source?.scenarioId ?? null,
        anchor,
        pass: allPassed,
        trials,
      };
      anchorAggregates[anchor].push(aggregate);
      if (!allPassed) anchorViolations.push({ id, anchor, reason: `${anchor}-anchor-violation` });
    }
  }

  const passKRate = ratio(passK, completeCases);
  const passAtKRate = ratio(passAtK, completeCases);
  const flakeRate = ratio(flake, completeCases);
  const reasons = [];
  let gate = 'pass';

  if (anchorViolations.length > 0) {
    gate = 'fail';
    reasons.push('anchor-violation');
  }
  if (safetyViolations.length > 0) {
    gate = 'fail';
    reasons.push('safety-skip-or-flake');
  }
  if (flakeRate !== null && flakeRate > flakeThreshold) {
    gate = 'fail';
    reasons.push('flake-threshold-exceeded');
  }
  if (completeCases < minCases) {
    if (gate !== 'fail') gate = 'insufficient-sample';
    reasons.push('complete-cases-below-design-minimum');
  }

  return {
    oracle: 'deterministic-fixture',
    design: { k, minCases, flakeThreshold },
    rawDenominator: {
      totalCases: cases.length,
      completeCases,
      incompleteCases: incompleteCases.length,
      excludedIncompleteCases: incompleteCases.length,
    },
    metrics: {
      passK: { numerator: passK, denominator: completeCases, rate: passKRate },
      passAtK: { numerator: passAtK, denominator: completeCases, rate: passAtKRate },
      flake: { numerator: flake, denominator: completeCases, rate: flakeRate, caseIds: flakeCaseIds },
    },
    incomplete: incompleteCases,
    anchors: anchorAggregates,
    anchorViolations,
    safetyViolations,
    gate,
    reasons,
  };
}

export function isTerminalReliabilityOutcome(outcome) {
  return TERMINAL_OUTCOMES.has(outcome);
}

export type ReliabilityOutcome = 'pass' | 'reject' | 'fail';

export type ReliabilityIncompleteStatus = 'missing' | 'timeout' | 'crashed' | 'skipped' | 'trial-count';

export interface ReliabilityTrial {
  status?: 'ok' | 'missing' | 'timeout' | 'crashed' | 'skipped';
  outcome?: ReliabilityOutcome;
}

export interface ReliabilityCase {
  id: string;
  scenarioId?: string | null;
  safety?: boolean;
  anchor?: 'positive' | 'negative' | null;
  trials: ReliabilityTrial[];
}

export interface ReliabilityFixture {
  design: {
    k: number;
    minCases: number;
    flakeThreshold: number;
  };
  cases: ReliabilityCase[];
}

export interface ReliabilityRatio {
  numerator: number;
  denominator: number;
  rate: number | null;
}

export interface ReliabilityAggregation {
  oracle: 'deterministic-fixture';
  design: Required<ReliabilityFixture['design']>;
  rawDenominator: {
    totalCases: number;
    completeCases: number;
    incompleteCases: number;
    excludedIncompleteCases: number;
  };
  metrics: {
    passK: ReliabilityRatio;
    passAtK: ReliabilityRatio;
    flake: ReliabilityRatio & { caseIds: string[] };
  };
  incomplete: Array<{
    id: string;
    scenarioId: string | null;
    status: ReliabilityIncompleteStatus;
    trialCount: number;
    expectedTrials: number;
    trials: ReliabilityTrial[];
  }>;
  anchors: {
    positive: Array<{ id: string; scenarioId: string | null; anchor: 'positive'; pass: boolean; trials: ReliabilityTrial[] }>;
    negative: Array<{ id: string; scenarioId: string | null; anchor: 'negative'; pass: boolean; trials: ReliabilityTrial[] }>;
  };
  anchorViolations: Array<{ id: string; anchor: 'positive' | 'negative'; reason: string }>;
  safetyViolations: Array<{ id: string; type: 'skip' | 'flake' }>;
  gate: 'pass' | 'fail' | 'insufficient-sample';
  reasons: string[];
}

export function aggregateReliability(fixture: ReliabilityFixture): ReliabilityAggregation;

export function isTerminalReliabilityOutcome(outcome: string): boolean;

#!/usr/bin/env node
